                window_index = reads / 4;
                element_index = reads % 4;
                expected_address = (2 * (window_index / OW) + element_index / 2) * W +
                                   2 * (window_index % OW) + element_index % 2;
                if((^img_rd_addr) === 1'bx || img_rd_addr != expected_address)begin
                    fail($sformatf("window=(%0d,%0d) k=%0d image address expected=%0d actual=%0d",
                                   window_index % OW, window_index / OW, element_index, expected_address,
                                   img_rd_addr));
                end
                img_rd_data <= image_memory[img_rd_addr];
                reads = reads + 1;
            end
            if(out_we)begin
                if(!active || busy !== 1'b1)begin
                    fail("write outside an active job");
                end
                if(previous_write)begin
                    fail("out_we must be a one-cycle pulse");
